/**
 * FieldType says what widget a scenario blank wants.
 *
 * A CLOSED ENUM, unlike `kind` beside it, and the split is on purpose: the
 * set of WIDGET SHAPES is the builder's own vocabulary and grows only when
 * the builder learns to render something new, while the set of THINGS a
 * widget can point at is content and grows with the rulebook. Adding a value
 * here is a real contract change because a client cannot render a shape it
 * has never heard of; adding a `kind` is not.
 *
 * @generated from enum dnd5e.api.authoring.v1alpha1.FieldType
 */
export enum FieldType {
  /**
   * @generated from enum value: FIELD_TYPE_UNSPECIFIED = 0;
   */
  UNSPECIFIED = 0,

  /**
   * Points at one authored thing in this dungeon, named by its id — a
   * placement's `place[].id`, an exit's `exits[].id` or a faction's
   * `factions[].id`. `kind` says which family the picker lists.
   *
   * @generated from enum value: FIELD_TYPE_ENTITY_REF = 1;
   */
  ENTITY_REF = 1,

  /**
   * Names an ability or skill check the scenario resolves. NOTHING BINDS ONE
   * YET: the first is the parchment shelf's "reading is a check" (design §9),
   * and the value is here because the descriptor's shape was designed with it
   * in view, not because a field of this type exists today. A builder may
   * ship without a widget for it and show the raw value.
   *
   * @generated from enum value: FIELD_TYPE_CHECK = 2;
   */
  CHECK = 2,
}

